CREATE OR REPLACE FUNCTION dbo.sp_DynamicSearch(
    p_table_name VARCHAR(128),
    p_filter_column VARCHAR(128),
    p_filter_value VARCHAR(256)
)
RETURNS TABLE
AS $$
DECLARE
    v_sql TEXT;
BEGIN
    -- Build dynamic SQL query
    v_sql := format('SELECT * FROM %I WHERE %I = $1',
                    p_table_name,
                    p_filter_column);

    -- Execute dynamic SQL and return results
    RETURN QUERY EXECUTE v_sql USING p_filter_value;
END;
$$ LANGUAGE plpgsql;
